export class InstanceMap {
    constructor(createNewObject) {
        this.instances = {};
        this.createNewObject = createNewObject;
    }
    get(id) {
        if (this.instances[id] == null) {
            this.instances[id] = this.createNewObject();
        }
        return this.instances[id];
    }
    delete(id) {
        const object = this.instances[id];
        delete this.instances[id];
        return object;
    }
}
